// Remove itens fantasma gerados pelo Always Output Data (bug #5 do projeto)
const limpa = arr => arr.filter(x => x && Object.keys(x).length > 0 && x.total !== undefined && x.total !== null);

const gerais = $('STATS GERAIS').first().json || {};
const msgs = $('MENSAGENS AGENTE').first().json || {};
const convenios = limpa($('RANKING CONVENIOS').all().map(i => i.json));
const horarios = limpa($('HORARIOS PICO').all().map(i => i.json));
const servicos = limpa($('RANKING SERVICOS').all().map(i => i.json));

// Fila ao vivo (aguardando + em atendimento) — independente do período selecionado
const filaBruta = $('FILA AO VIVO').all().map(i => i.json).filter(x => x && x.nome);
const aguardando = filaBruta.filter(x => x.status === 'pendente').map(x => ({
  nome: x.nome,
  tipo: x.tipo_solicitacao || 'novo',
  minutos: parseInt(x.minutos_espera) || 0
}));
const emAtendimento = filaBruta.filter(x => x.status === 'em_atendimento').map(x => ({
  nome: x.nome,
  tipo: x.tipo_solicitacao || 'novo',
  minutos: parseInt(x.minutos_espera) || 0
}));

const total = parseInt(gerais.total_agendamentos) || 0;

// Tempo trabalhado: estimativa (~8 min por pré-agendamento completo)
const minutosAgente = total * 8;
const horasAgente = Math.floor(minutosAgente / 60);
const minRestantes = minutosAgente % 60;

// Perguntas respondidas: DADO REAL — mensagens do agente em historico_conversas
const perguntasRespondidas = parseInt(msgs.msgs_agente) || 0;

return [{
  json: {
    periodo: {
      inicio: $('Coleta periodo').first().json.data_inicio,
      fim: $('Coleta periodo').first().json.data_fim
    },
    resumo: {
      total_agendamentos: total,
      total_concluidos: parseInt(gerais.total_concluidos) || 0,
      em_atendimento: parseInt(gerais.em_atendimento) || 0,
      pendentes: parseInt(gerais.pendentes) || 0,
      perguntas_respondidas: perguntasRespondidas,
      pacientes_unicos: parseInt(msgs.pacientes_unicos) || 0,
      tempo_agente_horas: horasAgente,
      tempo_agente_minutos: minRestantes
    },
    sla: {
      medio_minutos: parseFloat(gerais.sla_medio_minutos) || 0,
      minimo_minutos: parseFloat(gerais.sla_minimo_minutos) || 0,
      maximo_minutos: parseFloat(gerais.sla_maximo_minutos) || 0
    },
    convenios: convenios,
    horarios_pico: horarios,
    servicos: servicos,
    fila_aguardando: aguardando,
    fila_em_atendimento: emAtendimento
  }
}];
